WITH store_product AS ( SELECT ss.ss_item_sk, cd.cd_gender, SUM(ss.ss_net_profit) AS net_profit, SUM(ss.ss_quantity) AS qty, COUNT(DISTINCT ss.ss_customer_sk) AS distinct_customers FROM store_sales ss JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk GROUP BY ss.ss_item_sk, cd.cd_gender ), store_item_total AS ( SELECT ss_item_sk, SUM(net_profit) AS total_net_profit, SUM(qty) AS total_qty, SUM(distinct_customers) AS total_customers, DENSE_RANK() OVER (ORDER BY SUM(net_profit) DESC) AS profit_rank FROM store_product GROUP BY ss_item_sk HAVING SUM(net_profit) > 0 ), web_product AS ( SELECT ws.ws_item_sk, cd.cd_gender, SUM(ws.ws_net_profit) AS net_profit, SUM(ws.ws_quantity) AS qty, COUNT(DISTINCT ws.ws_bill_customer_sk) AS distinct_customers FROM web_sales ws JOIN customer_demographics cd ON ws.ws_bill_cdemo_sk = cd.cd_demo_sk GROUP BY ws.ws_item_sk, cd.cd_gender ), web_item_total AS ( SELECT ws_item_sk, SUM(net_profit) AS total_net_profit, SUM(qty) AS total_qty, SUM(distinct_customers) AS total_customers, DENSE_RANK() OVER (ORDER BY SUM(net_profit) DESC) AS profit_rank FROM web_product GROUP BY ws_item_sk HAVING SUM(net_profit) > 0 ) SELECT 'store' AS channel, sp.ss_item_sk AS item_sk, sit.profit_rank, sp.cd_gender, sp.net_profit, sp.qty, sp.distinct_customers, sp.net_profit / sit.total_net_profit AS profit_share_of_item, CASE WHEN sp.net_profit > 0.5 * sit.total_net_profit THEN 'High' ELSE 'Low' END AS gender_contrib_flag FROM store_product sp JOIN store_item_total sit ON sit.ss_item_sk = sp.ss_item_sk WHERE sit.profit_rank <= 10 UNION ALL SELECT 'web' AS channel, wp.ws_item_sk AS item_sk, wit.profit_rank, wp.cd_gender, wp.net_profit, wp.qty, wp.distinct_customers, wp.net_profit / wit.total_net_profit AS profit_share_of_item, CASE WHEN wp.net_profit > 0.5 * wit.total_net_profit THEN 'High' ELSE 'Low' END AS gender_contrib_flag FROM web_product wp JOIN web_item_total wit ON wit.ws_item_sk = wp.ws_item_sk WHERE wit.profit_rank <= 10 ORDER BY channel, profit_rank, cd_gender
